import { useState } from "react"
import { createRoot } from "react-dom/client"

const starting = [
  { id: 1, name: "Party jollof", fav: false },
  { id: 2, name: "Moi moi", fav: false },
  { id: 3, name: "Pepper soup", fav: false },
]

function Dishes() {
  const [dishes, setDishes] = useState(starting)
  const [name, setName] = useState("")

  function add(e) {
    e.preventDefault()
    if (!name.trim()) return
    setDishes([...dishes, { id: Date.now(), name: name.trim(), fav: false }])
    setName("")
  }

  return (
    <>
      <ul>
        {dishes.map((d) => (
          <li key={d.id} className={d.fav ? "fav" : ""}>
            <span>{d.name}</span>{" "}
            <button onClick={() => setDishes(dishes.map((x) => (x.id === d.id ? { ...x, fav: !x.fav } : x)))}>★</button>{" "}
            <button onClick={() => setDishes(dishes.filter((x) => x.id !== d.id))}>Remove</button>
          </li>
        ))}
      </ul>
      <form onSubmit={add}>
        <input id="new" placeholder="New dish" value={name} onChange={(e) => setName(e.target.value)} />
        <button>Add</button>
      </form>
    </>
  )
}

createRoot(document.getElementById("root")).render(<Dishes />)
